INSERT INTO public.study_tracks (slug, name, short_name, organ, banca, exam_date, edital_url, description, rules)
VALUES ('camara-cuiaba-2026', 'Câmara Municipal de Cuiabá-MT — Concurso 2026', 'Câmara de Cuiabá 2026', 'Câmara Municipal de Cuiabá-MT', 'Instituto Selecon',
        '2026-12-20', 'https://anexos-r2.selecao.net.br/uploads/779/concursos/102/anexos/5b03b63a-c8e5-47ff-b655-88572a17db55.pdf', 'Trilha completa baseada no Edital nº 001/2026-CMC (consolidado com as retificações 01 e 02). Questões no padrão Selecon (4 alternativas, uma correta), cobrindo todo o Anexo V, com novas questões publicadas automaticamente toda semana.', '{"prova_objetiva":"70 questões de múltipla escolha com 4 alternativas (A a D) e uma única resposta correta. Básicos e Gerais valem 1 ponto por questão; Específicos valem 1,75 ponto. Total: 100 pontos.","aprovacao":"Habilitado quem fizer no mínimo 40 pontos (40%) e não zerar nenhuma das áreas (Básicos, Gerais e Específicos).","discursiva":"Mesmo dia da objetiva. Tema de conhecimento específico do cargo, 20 a 30 linhas, 100 pontos (80 de conteúdo e 20 de correção formal). Só é corrigida até 20 vezes o número de vagas.","titulos":"Avaliação de títulos (classificatória) apenas para os cargos de nível superior.","desempate":"Após os critérios legais: maior nota em Específicos, depois em Gerais, depois em Básicos.","cronograma":[{"data":"2026-11-30","evento":"Fim das inscrições"},{"data":"2026-12-01","evento":"Último dia para pagamento da taxa"},{"data":"2026-12-09","evento":"Cartão de confirmação (local de prova)"},{"data":"2026-12-20","evento":"Provas objetiva e discursiva"},{"data":"2026-12-21","evento":"Gabarito preliminar"}]}'::jsonb)
ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, short_name = EXCLUDED.short_name, organ = EXCLUDED.organ,
  banca = EXCLUDED.banca, exam_date = EXCLUDED.exam_date, edital_url = EXCLUDED.edital_url,
  description = EXCLUDED.description, rules = EXCLUDED.rules;

INSERT INTO public.study_track_modules (track_id, slug, name, nivel, description, cargos, structure, display_order)
SELECT t.id, 'nivel-medio', 'Nível Médio', 'medio', 'Técnico Legislativo, Técnico Legislativo – Sonorização e Técnico Legislativo – Cerimonial. Vencimento inicial R$ 5.518,91 + auxílio-alimentação R$ 1.500 + auxílio-saúde R$ 1.000. Jornada de 30h.', ARRAY['Técnico Legislativo', 'Técnico Legislativo – Sonorização', 'Técnico Legislativo – Cerimonial']::text[],
       '[{"area":"Conhecimentos Básicos","questoes":15,"pontos_por_questao":1,"disciplinas":["Língua Portuguesa","Raciocínio Lógico e Matemático","Noções de Informática","Legislação"]},{"area":"Conhecimentos Gerais","questoes":15,"pontos_por_questao":1,"disciplinas":["História e Geografia de Mato Grosso","Noções de Ética e Filosofia","Relações Interpessoais"]},{"area":"Conhecimentos Específicos","questoes":40,"pontos_por_questao":1.75,"disciplinas":["Disciplina específica do cargo"]}]'::jsonb, 1
FROM public.study_tracks t WHERE t.slug = 'camara-cuiaba-2026'
ON CONFLICT (track_id, slug) DO UPDATE SET name = EXCLUDED.name, nivel = EXCLUDED.nivel,
  description = EXCLUDED.description, cargos = EXCLUDED.cargos, structure = EXCLUDED.structure,
  display_order = EXCLUDED.display_order;
INSERT INTO public.study_track_subjects (module_id, subject_id, area, cargo, syllabus, study_tips, weekly_target, ai_grounded_only, display_order)
SELECT m.id, s.id, 'Conhecimentos Básicos', NULL, '1. Leitura e interpretação de textos de variados gêneros discursivos. 2. Condições de produção de um texto e marcas composicionais de gêneros textuais. 3. Linguagem e adequação social: variedades linguísticas e seus determinantes sociais, regionais, históricos e individuais; registros formal e informal. 4. Aspectos linguísticos: fonética (prosódia, ortografia); morfologia (formação, classificação e flexão das palavras); sintaxe (concordâncias verbal e nominal, regências verbal e nominal, colocação pronominal, emprego de nomes, pronomes, conjunções, advérbios, modos e tempos verbais); semântica (polissemia, paronímia, homonímia, denotação e conotação). 5. Textualidade: coesão, coerência, intertextualidade, argumentação. 6. Pontuação. 7. Tipos de discurso: direto e indireto.', 'A Selecon cobra muita interpretação com texto-base, valor semântico de conectivos, crase, regência, concordância e pontuação. Treine reescrita de frases (mantém o sentido? mantém a correção?).', 15, false, 1
FROM public.study_track_modules m JOIN public.study_tracks t ON t.id = m.track_id, public.subjects s
WHERE t.slug = 'camara-cuiaba-2026' AND m.slug = 'nivel-medio' AND s.slug = 'cmc26-lingua-portuguesa'
ON CONFLICT (module_id, subject_id) DO UPDATE SET area = EXCLUDED.area, cargo = EXCLUDED.cargo,
  syllabus = EXCLUDED.syllabus, study_tips = EXCLUDED.study_tips, weekly_target = EXCLUDED.weekly_target,
  ai_grounded_only = EXCLUDED.ai_grounded_only,
  display_order = EXCLUDED.display_order;
INSERT INTO public.study_track_subjects (module_id, subject_id, area, cargo, syllabus, study_tips, weekly_target, ai_grounded_only, display_order)
SELECT m.id, s.id, 'Conhecimentos Básicos', NULL, '1. Operações com conjuntos. 2. Raciocínio lógico numérico: problemas com números reais e raciocínio sequencial. 3. Proposição: valores lógicos, conectivos e negação. 4. Argumentação lógica e diagramas lógicos. 5. Equivalências e implicações lógicas. 6. Quantificadores universal e existencial. 7. Problemas de contagem: princípios aditivo e multiplicativo.', 'Domine negação de proposições compostas (De Morgan, negação do ''se... então''), equivalência contrapositiva, diagramas de Venn e princípio multiplicativo.', 15, false, 2
FROM public.study_track_modules m JOIN public.study_tracks t ON t.id = m.track_id, public.subjects s
WHERE t.slug = 'camara-cuiaba-2026' AND m.slug = 'nivel-medio' AND s.slug = 'cmc26-raciocinio-logico'
ON CONFLICT (module_id, subject_id) DO UPDATE SET area = EXCLUDED.area, cargo = EXCLUDED.cargo,
  syllabus = EXCLUDED.syllabus, study_tips = EXCLUDED.study_tips, weekly_target = EXCLUDED.weekly_target,
  ai_grounded_only = EXCLUDED.ai_grounded_only,
  display_order = EXCLUDED.display_order;
INSERT INTO public.study_track_subjects (module_id, subject_id, area, cargo, syllabus, study_tips, weekly_target, ai_grounded_only, display_order)
SELECT m.id, s.id, 'Conhecimentos Básicos', NULL, '1. Microinformática: hardware, software, dispositivos de entrada, saída e armazenamento. 2. Windows 10 e 11 e distribuições Linux. 3. Microsoft Office/365 (Word, Excel, PowerPoint) e LibreOffice 7+ (Writer, Calc, Impress): recursos e atalhos. 4. Redes e internet: protocolos, TCP/IP, navegadores (Edge, Firefox, Chrome), e-mail e colaboração. 5. Computação em nuvem, armazenamento e serviços online; redes sociais. 6. Segurança da informação: vírus, malware, phishing, engenharia social, backup, firewall, antivírus, 2FA. 7. Noções da LGPD (Lei nº 13.709/2018).', 'Atalhos de teclado (Word x Writer, Excel x Calc), funções de planilha (SE, SOMASE, PROCV), protocolos (HTTP/HTTPS, SMTP, POP3, IMAP), tipos de malware e bases legais da LGPD.', 15, false, 3
FROM public.study_track_modules m JOIN public.study_tracks t ON t.id = m.track_id, public.subjects s
WHERE t.slug = 'camara-cuiaba-2026' AND m.slug = 'nivel-medio' AND s.slug = 'cmc26-informatica'
ON CONFLICT (module_id, subject_id) DO UPDATE SET area = EXCLUDED.area, cargo = EXCLUDED.cargo,
  syllabus = EXCLUDED.syllabus, study_tips = EXCLUDED.study_tips, weekly_target = EXCLUDED.weekly_target,
  ai_grounded_only = EXCLUDED.ai_grounded_only,
  display_order = EXCLUDED.display_order;
INSERT INTO public.study_track_subjects (module_id, subject_id, area, cargo, syllabus, study_tips, weekly_target, ai_grounded_only, display_order)
SELECT m.id, s.id, 'Conhecimentos Básicos', NULL, '1. Lei Orgânica do Município de Cuiabá-MT. 2. Regimento Interno da Câmara Municipal de Cuiabá (Resolução nº 08/2016). 3. Lei Complementar nº 93/2003 (Estatuto dos Servidores). 4. Lei Complementar nº 235/2011 (PCCV da Câmara), com as alterações da LC nº 609/2026.', 'Decore prazos e quóruns: posse em 30 dias (prorrogável), exercício em 5 dias, estágio probatório de 3 anos, prescrição disciplinar (5 anos/2 anos/180 dias), quóruns de maioria absoluta e 2/3 do Regimento, jornada de 30h (art. 36 da LC 235).', 15, true, 4
FROM public.study_track_modules m JOIN public.study_tracks t ON t.id = m.track_id, public.subjects s
WHERE t.slug = 'camara-cuiaba-2026' AND m.slug = 'nivel-medio' AND s.slug = 'cmc26-legislacao'
ON CONFLICT (module_id, subject_id) DO UPDATE SET area = EXCLUDED.area, cargo = EXCLUDED.cargo,
  syllabus = EXCLUDED.syllabus, study_tips = EXCLUDED.study_tips, weekly_target = EXCLUDED.weekly_target,
  ai_grounded_only = EXCLUDED.ai_grounded_only,
  display_order = EXCLUDED.display_order;
INSERT INTO public.study_track_subjects (module_id, subject_id, area, cargo, syllabus, study_tips, weekly_target, ai_grounded_only, display_order)
SELECT m.id, s.id, 'Conhecimentos Gerais', NULL, 'História de MT — Colônia: bandeirantes, escravidão indígena e ouro; fundação de Cuiabá; Vila Bela e a Capitania de Mato Grosso; escravidão negra. Império: crise da mineração; Rusga; quilombos; presidentes de província; Guerra da Tríplice Aliança; economia pós-guerra; fim do Império. República: coronelismo; usinas de açúcar e pecuária; relações de trabalho; Era Vargas; política fundiária e conflitos no campo; governadores; temas atuais. Geografia de MT: Centro-Oeste, geopolítica, ocupação do território, aspectos físicos e biomas (Amazônia, Cerrado, Pantanal), aspectos político-administrativos e socioeconômicos, formação étnica, programas governamentais e fronteira agrícola, economia no contexto nacional, urbanização.', 'Datas-chave: 1719 (descoberta do ouro no Coxipó), 8/4/1719 (ata de fundação), 1727 (Vila Real do Senhor Bom Jesus de Cuiabá), 1748 (Capitania), 1752 (Vila Bela), 1834 (Rusga), 1835 (capital para Cuiabá), 1977/1979 (divisão do estado). Biomas e agronegócio aparecem sempre.', 15, false, 5
FROM public.study_track_modules m JOIN public.study_tracks t ON t.id = m.track_id, public.subjects s
WHERE t.slug = 'camara-cuiaba-2026' AND m.slug = 'nivel-medio' AND s.slug = 'cmc26-historia-geografia-mt'
ON CONFLICT (module_id, subject_id) DO UPDATE SET area = EXCLUDED.area, cargo = EXCLUDED.cargo,
  syllabus = EXCLUDED.syllabus, study_tips = EXCLUDED.study_tips, weekly_target = EXCLUDED.weekly_target,
  ai_grounded_only = EXCLUDED.ai_grounded_only,
  display_order = EXCLUDED.display_order;
INSERT INTO public.study_track_subjects (module_id, subject_id, area, cargo, syllabus, study_tips, weekly_target, ai_grounded_only, display_order)
SELECT m.id, s.id, 'Conhecimentos Gerais', NULL, '1. Fundamentos da Filosofia. 2. Filosofia moral: ética ou filosofia moral. 3. Consciência crítica e filosofia. 4. Valores éticos/morais e cultura. 5. Juízos de fato e juízos de valor. 6. Ética e cidadania. 7. Racionalismo ético. 8. Ética e liberdade.', 'Distinga juízo de fato x juízo de valor, ética x moral, heteronomia x autonomia (Kant), e as visões de liberdade (Sartre, Espinosa). A base é o livro ''Convite à Filosofia'' (Marilena Chaui).', 15, false, 6
FROM public.study_track_modules m JOIN public.study_tracks t ON t.id = m.track_id, public.subjects s
WHERE t.slug = 'camara-cuiaba-2026' AND m.slug = 'nivel-medio' AND s.slug = 'cmc26-etica-filosofia'
ON CONFLICT (module_id, subject_id) DO UPDATE SET area = EXCLUDED.area, cargo = EXCLUDED.cargo,
  syllabus = EXCLUDED.syllabus, study_tips = EXCLUDED.study_tips, weekly_target = EXCLUDED.weekly_target,
  ai_grounded_only = EXCLUDED.ai_grounded_only,
  display_order = EXCLUDED.display_order;
INSERT INTO public.study_track_subjects (module_id, subject_id, area, cargo, syllabus, study_tips, weekly_target, ai_grounded_only, display_order)
SELECT m.id, s.id, 'Conhecimentos Gerais', NULL, '1. Relações humanas/interpessoais. 2. Comunicação interpessoal. 3. Características de um bom atendimento. 4. Postura profissional. 5. Integração. 6. Empatia. 7. Capacidade de ouvir. 8. Argumentação flexível.', 'Questões situacionais: escolha sempre a conduta que combina escuta ativa, empatia, cordialidade, objetividade e respeito às normas — sem se omitir nem ''resolver'' fora das regras.', 15, false, 7
FROM public.study_track_modules m JOIN public.study_tracks t ON t.id = m.track_id, public.subjects s
WHERE t.slug = 'camara-cuiaba-2026' AND m.slug = 'nivel-medio' AND s.slug = 'cmc26-relacoes-interpessoais'
ON CONFLICT (module_id, subject_id) DO UPDATE SET area = EXCLUDED.area, cargo = EXCLUDED.cargo,
  syllabus = EXCLUDED.syllabus, study_tips = EXCLUDED.study_tips, weekly_target = EXCLUDED.weekly_target,
  ai_grounded_only = EXCLUDED.ai_grounded_only,
  display_order = EXCLUDED.display_order;
INSERT INTO public.study_track_subjects (module_id, subject_id, area, cargo, syllabus, study_tips, weekly_target, ai_grounded_only, display_order)
SELECT m.id, s.id, 'Conhecimentos Específicos', 'Técnico Legislativo', '1. Estado, governo e Administração Pública. 2. Organização administrativa: Administração Direta e Indireta; órgãos; agentes (cargo, emprego, função). 3. Direito Administrativo: princípios, poderes, atos administrativos. 4. Controle da Administração e responsabilidade civil do Estado. 5. Direitos e garantias fundamentais; direitos sociais; cidadania; arts. 37 a 41 da CF. 6. Poder Legislativo Municipal: Câmara, Mesa, Plenário, comissões. 7. Processo legislativo e técnica legislativa (LC 95/1998). 8. Redação oficial: comunicações, ofícios, memorandos, requerimentos, atas, sinopses, relatórios. 9. Arquivologia. 10. Atendimento ao público. 11. Noções de contabilidade pública: receita, despesa e orçamento. 12. Noções de higiene e segurança do trabalho. 13. Redação Oficial.', 'Peso 1,75 por questão: é aqui que se passa. Foque em atos administrativos, arts. 37-41 da CF, Manual de Redação da Presidência (3ª ed.), LC 95/1998 e arquivologia (teoria das três idades).', 15, false, 8
FROM public.study_track_modules m JOIN public.study_tracks t ON t.id = m.track_id, public.subjects s
WHERE t.slug = 'camara-cuiaba-2026' AND m.slug = 'nivel-medio' AND s.slug = 'cmc26-tecnico-legislativo'
ON CONFLICT (module_id, subject_id) DO UPDATE SET area = EXCLUDED.area, cargo = EXCLUDED.cargo,
  syllabus = EXCLUDED.syllabus, study_tips = EXCLUDED.study_tips, weekly_target = EXCLUDED.weekly_target,
  ai_grounded_only = EXCLUDED.ai_grounded_only,
  display_order = EXCLUDED.display_order;
INSERT INTO public.study_track_subjects (module_id, subject_id, area, cargo, syllabus, study_tips, weekly_target, ai_grounded_only, display_order)
SELECT m.id, s.id, 'Conhecimentos Específicos', 'Técnico Legislativo – Sonorização', '1. Acústica e fundamentos de áudio: propriedades do som, frequência, amplitude, decibel e acústica de ambientes. 2. Equipamentos: microfones, mesas analógicas e digitais, amplificadores, caixas, processadores, interfaces, cabos, conectores. 3. Configuração, operação, monitoramento e ajuste de sistemas de sonorização, gravação e reprodução. 4. Instalação, teste, operação e manutenção em plenários, auditórios, sessões e audiências públicas. 5. Captação, gravação, edição, tratamento e armazenamento de áudio: formatos, mídias e arquivos. 6. Projetos de sonorização e gravação. 7. Acompanhamento de eventos e transmissões. 8. Segurança em instalações elétricas, montagem e prevenção de acidentes.', 'Conheça padrões de microfonação (cardioide, supercardioide, omni), phantom power (+48 V), balanceamento (XLR/TRS), ganho x volume, realimentação (microfonia), taxas de amostragem e formatos (WAV, MP3, FLAC).', 15, false, 9
FROM public.study_track_modules m JOIN public.study_tracks t ON t.id = m.track_id, public.subjects s
WHERE t.slug = 'camara-cuiaba-2026' AND m.slug = 'nivel-medio' AND s.slug = 'cmc26-sonorizacao'
ON CONFLICT (module_id, subject_id) DO UPDATE SET area = EXCLUDED.area, cargo = EXCLUDED.cargo,
  syllabus = EXCLUDED.syllabus, study_tips = EXCLUDED.study_tips, weekly_target = EXCLUDED.weekly_target,
  ai_grounded_only = EXCLUDED.ai_grounded_only,
  display_order = EXCLUDED.display_order;
INSERT INTO public.study_track_subjects (module_id, subject_id, area, cargo, syllabus, study_tips, weekly_target, ai_grounded_only, display_order)
SELECT m.id, s.id, 'Conhecimentos Específicos', 'Técnico Legislativo – Cerimonial', '1. Cerimonial, protocolo e etiqueta na Administração Pública. 2. Ordem de precedência e tratamentos protocolares (Decreto nº 70.274/1972). 3. Planejamento e execução de eventos: solenidades, sessões especiais e solenes, audiências públicas, posses, homenagens, inaugurações. 4. Símbolos oficiais: bandeiras, brasões e hinos (Lei nº 5.700/1971). 5. Composição de mesas e disposição de autoridades. 6. Roteiros, ordens de serviço, programas, convites, listas de presença, certificados. 7. Recepção de autoridades e convidados. 8. Comunicação institucional aplicada ao cerimonial. 9. Sessões solenes, especiais e audiências públicas do Regimento Interno da Câmara de Cuiabá.', 'Precedência: anfitrião ocupa o centro; a direita do centro é o lugar de honra. A Bandeira Nacional ocupa o lugar de honra (centro, ou o mais próximo do centro e à direita dele — art. 31 da Lei 5.700/1971). Estude também a ordem de precedência do Decreto 70.274/1972 e as regras de execução do Hino Nacional.', 15, false, 10
FROM public.study_track_modules m JOIN public.study_tracks t ON t.id = m.track_id, public.subjects s
WHERE t.slug = 'camara-cuiaba-2026' AND m.slug = 'nivel-medio' AND s.slug = 'cmc26-cerimonial'
ON CONFLICT (module_id, subject_id) DO UPDATE SET area = EXCLUDED.area, cargo = EXCLUDED.cargo,
  syllabus = EXCLUDED.syllabus, study_tips = EXCLUDED.study_tips, weekly_target = EXCLUDED.weekly_target,
  ai_grounded_only = EXCLUDED.ai_grounded_only,
  display_order = EXCLUDED.display_order;

INSERT INTO public.study_track_modules (track_id, slug, name, nivel, description, cargos, structure, display_order)
SELECT t.id, 'nivel-superior', 'Nível Superior', 'superior', 'Analista Legislativo (geral, TI, Segurança do Trabalho, Psicólogo, Assistente Social e Jornalismo), Contador e Controlador Interno. Vencimento inicial de R$ 7.070,51 (Analista) a R$ 11.629,67 (Contador e Controlador Interno), mais auxílios de R$ 2.500. Jornada de 30h.', ARRAY['Analista Legislativo', 'Analista Legislativo – Tecnologia da Informação', 'Analista Legislativo – Segurança do Trabalho', 'Analista Legislativo – Psicólogo', 'Analista Legislativo – Assistente Social', 'Analista Legislativo – Jornalismo', 'Contador', 'Controlador Interno']::text[],
       '[{"area":"Conhecimentos Básicos","questoes":15,"pontos_por_questao":1,"disciplinas":["Língua Portuguesa","Raciocínio Lógico e Matemático","Noções de Informática"]},{"area":"Conhecimentos Gerais","questoes":15,"pontos_por_questao":1,"disciplinas":["História e Geografia de Mato Grosso","Noções de Ética e Filosofia","Relações Interpessoais","Noções de Administração Pública"]},{"area":"Conhecimentos Específicos","questoes":40,"pontos_por_questao":1.75,"disciplinas":["Legislação","Disciplina específica do cargo"]}]'::jsonb, 2
FROM public.study_tracks t WHERE t.slug = 'camara-cuiaba-2026'
ON CONFLICT (track_id, slug) DO UPDATE SET name = EXCLUDED.name, nivel = EXCLUDED.nivel,
  description = EXCLUDED.description, cargos = EXCLUDED.cargos, structure = EXCLUDED.structure,
  display_order = EXCLUDED.display_order;
INSERT INTO public.study_track_subjects (module_id, subject_id, area, cargo, syllabus, study_tips, weekly_target, ai_grounded_only, display_order)
SELECT m.id, s.id, 'Conhecimentos Básicos', NULL, '1. Leitura e interpretação de textos de variados gêneros discursivos. 2. Condições de produção de um texto e marcas composicionais de gêneros textuais. 3. Linguagem e adequação social: variedades linguísticas; registros formal e informal. 4. Fonética (prosódia, ortografia); morfologia; sintaxe (concordância, regência, colocação pronominal, emprego de classes de palavras, modos e tempos verbais); semântica (polissemia, paronímia, homonímia, denotação e conotação). 5. Coesão, coerência, intertextualidade, argumentação. 6. Pontuação. 7. Discurso direto e indireto.', 'Mesmo conteúdo do nível médio, com textos mais densos. Atenção a reescritas, valor de conectivos concessivos/conclusivos, crase e sentido de palavras no contexto.', 15, false, 1
FROM public.study_track_modules m JOIN public.study_tracks t ON t.id = m.track_id, public.subjects s
WHERE t.slug = 'camara-cuiaba-2026' AND m.slug = 'nivel-superior' AND s.slug = 'cmc26-lingua-portuguesa'
ON CONFLICT (module_id, subject_id) DO UPDATE SET area = EXCLUDED.area, cargo = EXCLUDED.cargo,
  syllabus = EXCLUDED.syllabus, study_tips = EXCLUDED.study_tips, weekly_target = EXCLUDED.weekly_target,
  ai_grounded_only = EXCLUDED.ai_grounded_only,
  display_order = EXCLUDED.display_order;
INSERT INTO public.study_track_subjects (module_id, subject_id, area, cargo, syllabus, study_tips, weekly_target, ai_grounded_only, display_order)
SELECT m.id, s.id, 'Conhecimentos Básicos', NULL, '1. Operações com conjuntos. 2. Raciocínio lógico numérico e sequencial. 3. Proposições: valores lógicos, conectivos, negação e tabela-verdade; tautologias; condição necessária e suficiente. 4. Argumentação lógica, estruturas e diagramas lógicos. 5. Equivalências e implicações. 6. Quantificadores. 7. Contagem: princípios aditivo e multiplicativo; arranjos, combinações e permutações. 8. Noções de probabilidade.', 'No superior entram tabela-verdade, tautologia, condição necessária/suficiente, análise combinatória e probabilidade — questões marcadas como ''nível superior'' na trilha.', 15, false, 2
FROM public.study_track_modules m JOIN public.study_tracks t ON t.id = m.track_id, public.subjects s
WHERE t.slug = 'camara-cuiaba-2026' AND m.slug = 'nivel-superior' AND s.slug = 'cmc26-raciocinio-logico'
