INSERT INTO public.study_track_subjects (module_id, subject_id, area, cargo, syllabus, study_tips, weekly_target, ai_grounded_only, display_order)
SELECT m.id, s.id, 'Conhecimentos Gerais', NULL, '1. Estado, governo e administração pública: conceitos, elementos, poderes, organização, natureza, fins e princípios. 2. Organização administrativa do Estado. 3. Administração direta e indireta. 4. Agentes públicos: espécies, classificação, poderes, deveres e prerrogativas; cargo, emprego e função. 5. Poderes administrativos. 6. Atos administrativos: conceito, requisitos, atributos, classificação, espécies e invalidação. 7. Controle e responsabilização da administração: administrativo, judicial, legislativo; responsabilidade civil.', 'Exclusiva do nível superior na área de Conhecimentos Gerais. Requisitos (COMFIFOMOB), atributos (PATI), anulação x revogação (Súmula 473 STF) e responsabilidade objetiva (art. 37, §6º, CF).', 15, false, 7
FROM public.study_track_modules m JOIN public.study_tracks t ON t.id = m.track_id, public.subjects s
WHERE t.slug = 'camara-cuiaba-2026' AND m.slug = 'nivel-superior' AND s.slug = 'cmc26-administracao-publica'
ON CONFLICT (module_id, subject_id) DO UPDATE SET area = EXCLUDED.area, cargo = EXCLUDED.cargo,
