SELECT m.id, s.id, 'Conhecimentos Específicos', NULL, '1. Lei Orgânica do Município de Cuiabá-MT. 2. Regimento Interno da Câmara Municipal de Cuiabá (Resolução nº 08/2016). 3. LC nº 93/2003 (Estatuto dos Servidores). 4. LC nº 235/2011 (PCCV da Câmara), com as alterações da LC nº 609/2026.', 'No nível superior a Legislação está em Conhecimentos Específicos (vale 1,75 por questão). Prioridade máxima.', 15, true, 8
FROM public.study_track_modules m JOIN public.study_tracks t ON t.id = m.track_id, public.subjects s
WHERE t.slug = 'camara-cuiaba-2026' AND m.slug = 'nivel-superior' AND s.slug = 'cmc26-legislacao'
ON CONFLICT (module_id, subject_id) DO UPDATE SET area = EXCLUDED.area, cargo = EXCLUDED.cargo,
  syllabus = EXCLUDED.syllabus, study_tips = EXCLUDED.study_tips, weekly_target = EXCLUDED.weekly_target,
