INSERT INTO public.study_track_subjects (module_id, subject_id, area, cargo, syllabus, study_tips, weekly_target, ai_grounded_only, display_order)
SELECT m.id, s.id, 'Conhecimentos Específicos', 'Analista Legislativo', 'Direito Administrativo: princípios; Administração direta e indireta; atos; poderes; contratos; licitação (Lei nº 14.133/2021); processo administrativo; agentes; serviços públicos; controle; improbidade; bens públicos. Direito Constitucional: direitos e garantias fundamentais; Municípios. Administração Pública: organização governamental; paradigmas (burocrática, Estado de bem-estar, nova gestão pública); governança; políticas públicas (ciclo, formulação e avaliação); planejamento e orçamento (PPA, LDO, LOA); PPP, consórcios, terceirização, OS, OSCIP, agências; governabilidade e accountability; estratégia (5 Ps de Mintzberg); gestão por resultados e indicadores.', 'Lei 14.133/2021 (modalidades, fases, dispensa/inexigibilidade), Lei 8.429/1992 com a reforma da Lei 14.230/2021 (dolo obrigatório) e ciclo de políticas públicas são campeões de cobrança.', 15, false, 9
FROM public.study_track_modules m JOIN public.study_tracks t ON t.id = m.track_id, public.subjects s
WHERE t.slug = 'camara-cuiaba-2026' AND m.slug = 'nivel-superior' AND s.slug = 'cmc26-analista-legislativo'
ON CONFLICT (module_id, subject_id) DO UPDATE SET area = EXCLUDED.area, cargo = EXCLUDED.cargo,
  syllabus = EXCLUDED.syllabus, study_tips = EXCLUDED.study_tips, weekly_target = EXCLUDED.weekly_target,
  ai_grounded_only = EXCLUDED.ai_grounded_only,
  display_order = EXCLUDED.display_order;
INSERT INTO public.study_track_subjects (module_id, subject_id, area, cargo, syllabus, study_tips, weekly_target, ai_grounded_only, display_order)
SELECT m.id, s.id, 'Conhecimentos Específicos', 'Analista Legislativo – Tecnologia da Informação', 'Arquitetura de computadores; algoritmos, estruturas de dados e POO; engenharia de software, requisitos, testes e métodos ágeis; web e APIs REST (HTML, CSS, JavaScript); banco de dados relacional e SQL; redes (OSI, TCP/IP, IP, equipamentos, cabeamento, serviços); Windows e Linux; segurança da informação (criptografia, certificados, firewall, vulnerabilidades, pentest, incidentes, ISO 27001/27002); governança de TI (PDTI, ITIL, projetos, riscos); Git, CI/CD e contêineres; BI e análise de dados; contratações de TI e Lei 14.133/2021; LGPD e LAI; suporte e documentação.', 'SQL (JOIN, GROUP BY/HAVING), normalização, máscaras de sub-rede, portas TCP/UDP, criptografia simétrica x assimétrica, Scrum e comandos Linux/Git são os tópicos mais cobrados.', 15, false, 10
FROM public.study_track_modules m JOIN public.study_tracks t ON t.id = m.track_id, public.subjects s
WHERE t.slug = 'camara-cuiaba-2026' AND m.slug = 'nivel-superior' AND s.slug = 'cmc26-analista-ti'
ON CONFLICT (module_id, subject_id) DO UPDATE SET area = EXCLUDED.area, cargo = EXCLUDED.cargo,
  syllabus = EXCLUDED.syllabus, study_tips = EXCLUDED.study_tips, weekly_target = EXCLUDED.weekly_target,
  ai_grounded_only = EXCLUDED.ai_grounded_only,
  display_order = EXCLUDED.display_order;
INSERT INTO public.study_track_subjects (module_id, subject_id, area, cargo, syllabus, study_tips, weekly_target, ai_grounded_only, display_order)
SELECT m.id, s.id, 'Conhecimentos Específicos', 'Analista Legislativo – Segurança do Trabalho', 'Legislação de SST (CF art. 7º XXII e XXIII, CLT Cap. V, Lei 8.213/1991, NRs 1, 5, 6, 7, 10, 15, 16, 17, 18, 23 e 35); GRO/PGR, PCMSO, LTCAT, mapas de risco; higiene ocupacional; ergonomia; segurança em máquinas e instalações; EPC e EPI; prevenção e combate a incêndio; investigação de acidentes e CAT; laudos, pareceres e vistorias; engenharia civil aplicada; fiscalização de obras; licitações de obras (Lei 14.133/2021); meio ambiente do trabalho; treinamentos; ética profissional.', 'NR-1 (GRO/PGR), NR-5 (CIPA), NR-6 (EPI/CA), NR-15/16 (insalubridade 10/20/40% x periculosidade 30%), NR-35 (altura > 2 m) e NR-10 (tensões e SEP) concentram a prova.', 15, false, 11
FROM public.study_track_modules m JOIN public.study_tracks t ON t.id = m.track_id, public.subjects s
WHERE t.slug = 'camara-cuiaba-2026' AND m.slug = 'nivel-superior' AND s.slug = 'cmc26-seguranca-trabalho'
ON CONFLICT (module_id, subject_id) DO UPDATE SET area = EXCLUDED.area, cargo = EXCLUDED.cargo,
  syllabus = EXCLUDED.syllabus, study_tips = EXCLUDED.study_tips, weekly_target = EXCLUDED.weekly_target,
  ai_grounded_only = EXCLUDED.ai_grounded_only,
