INSERT INTO public.study_track_subjects (module_id, subject_id, area, cargo, syllabus, study_tips, weekly_target, ai_grounded_only, display_order)
SELECT m.id, s.id, 'Conhecimentos Específicos', 'Analista Legislativo – Assistente Social', 'Fundamentos históricos e teórico-metodológicos do Serviço Social; questão social; Lei 8.662/1993 e Código de Ética (Res. CFESS 273/1993); seguridade social (CF arts. 194 a 204); SUAS, LOAS, PNAS; planejamento e gestão de políticas sociais; instrumentais técnico-operativos (estudo social, entrevista, visita, parecer, laudo, perícia); projetos; direitos humanos, família, violência, controle social; ECA, Estatuto da Pessoa Idosa e LBI; assessoria, supervisão de estágio, trabalho interdisciplinar; pesquisa social e documentos técnicos.', 'Diferencie competências (art. 4º) de atribuições privativas (art. 5º) da Lei 8.662/1993; tripé da seguridade; BPC (art. 20 da LOAS); princípios do Código de Ética.', 15, false, 13
