-- Língua Portuguesa: 54 questoes
INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Leia o trecho: "A transparência legislativa não se esgota na publicação de atos no diário oficial. Ela exige linguagem acessível, dados abertos e canais que permitam ao cidadão não apenas saber o que foi decidido, mas compreender por que foi decidido." A ideia central do trecho é que a transparência:', ARRAY['é responsabilidade exclusiva do cidadão, que deve buscar as informações', 'se restringe à publicação dos atos no diário oficial, como determina a lei', 'exige mais do que a simples publicação formal dos atos, alcançando a compreensão das decisões pelo cidadão', 'deve priorizar os dados abertos em detrimento da linguagem acessível']::text[], 2, 'Língua Portuguesa', 'Médio', 'O trecho afirma que a transparência ''não se esgota'' na publicação e exige compreensão do ''porquê'' das decisões. As demais alternativas contrariam ou extrapolam o texto.', s.id, false, 'Interpretação de texto', 'autoral', NULL, '7fee49fb75e9e99d544e9e0cfee12cb7c7eb943bae5174cb97736f48be9fdc2e'
FROM public.subjects s WHERE s.slug = 'cmc26-lingua-portuguesa'
ON CONFLICT (content_hash) DO UPDATE SET
  alternativas = EXCLUDED.alternativas, correta = EXCLUDED.correta, categoria = EXCLUDED.categoria,
  dificuldade = EXCLUDED.dificuldade, explicacao = EXCLUDED.explicacao, topico = EXCLUDED.topico, nivel = EXCLUDED.nivel
WHERE questions.origem = 'autoral';
INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'No trecho "Ela exige linguagem acessível, dados abertos e canais que permitam ao cidadão não apenas saber o que foi decidido, mas compreender por que foi decidido", a expressão "não apenas... mas" estabelece relação de:', ARRAY['condição, necessária ao primeiro elemento', 'adição, com ênfase no segundo elemento', 'conclusão, decorrente do primeiro elemento', 'oposição, anulando o primeiro elemento']::text[], 1, 'Língua Portuguesa', 'Médio', 'A correlação ''não apenas... mas (também)'' é aditiva: soma as duas ideias, destacando a segunda. Não há anulação do primeiro termo.', s.id, false, 'Interpretação de texto', 'autoral', NULL, 'c70d2738e158df081fa688bcbf9d7c1a45bea6aa25852242c28af1fbca0fb740'
FROM public.subjects s WHERE s.slug = 'cmc26-lingua-portuguesa'
ON CONFLICT (content_hash) DO UPDATE SET
  alternativas = EXCLUDED.alternativas, correta = EXCLUDED.correta, categoria = EXCLUDED.categoria,
  dificuldade = EXCLUDED.dificuldade, explicacao = EXCLUDED.explicacao, topico = EXCLUDED.topico, nivel = EXCLUDED.nivel
WHERE questions.origem = 'autoral';
INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Em "A transparência legislativa não se esgota na publicação de atos no diário oficial. Ela exige linguagem acessível", o pronome "Ela" retoma:', ARRAY['a publicação de atos', 'o diário oficial', 'a linguagem acessível', 'a transparência legislativa']::text[], 3, 'Língua Portuguesa', 'Fácil', '''Ela'' é elemento coesivo anafórico que retoma o sujeito da oração anterior, ''a transparência legislativa''.', s.id, false, 'Coesão referencial', 'autoral', NULL, '8dcc28bee13841a828acedc3996b4d94ab5445552593f7d46aafa205cc34c8d7'
FROM public.subjects s WHERE s.slug = 'cmc26-lingua-portuguesa'
ON CONFLICT (content_hash) DO UPDATE SET
