INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Assinale a alternativa em que o emprego do acento indicativo de crase está correto.', ARRAY['O vereador se dirigiu à todos os presentes no plenário.', 'O documento foi entregue à uma assessora da Mesa.', 'O servidor compareceu à sessão ordinária de terça-feira.', 'A audiência começará à partir das nove horas.']::text[], 2, 'Língua Portuguesa', 'Médio', '''Comparecer a'' + ''a sessão'' = à. Não há crase antes de pronome indefinido (''todos''), antes de verbo (''partir'') nem antes de artigo indefinido (''uma'').', s.id, false, 'Crase', 'autoral', NULL, '50729ad172ae84fdbad80779e464a3e81f5ecfc86fc72df05fabc810f84eca9e'
FROM public.subjects s WHERE s.slug = 'cmc26-lingua-portuguesa'
ON CONFLICT (content_hash) DO UPDATE SET
  alternativas = EXCLUDED.alternativas, correta = EXCLUDED.correta, categoria = EXCLUDED.categoria,
  dificuldade = EXCLUDED.dificuldade, explicacao = EXCLUDED.explicacao, topico = EXCLUDED.topico, nivel = EXCLUDED.nivel
WHERE questions.origem = 'autoral';
INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Considere as frases: I. Fui à Cuiabá dos meus avós. II. Refiro-me àquela proposta de emenda. III. Assisti à votação do projeto. IV. Entreguei o ofício a Vossa Excelência. Está correto o que se afirma em:', ARRAY['I, II, III e IV', 'apenas II e III', 'apenas I e IV', 'apenas II, III e IV']::text[], 0, 'Língua Portuguesa', 'Médio', 'I: nome de cidade especificado admite artigo (''a Cuiabá dos meus avós''), logo há crase. II: a + aquela = àquela. III: ''assistir'' (ver) rege ''a'' + a votação. IV: não há crase antes de pronome de tratamento como ''Vossa Excelência''. Todas corretas.', s.id, false, 'Crase', 'autoral', NULL, '9e30b721dd487aa5074e402b3376fdaab3f327561a398e09d779c68c72b1b552'
FROM public.subjects s WHERE s.slug = 'cmc26-lingua-portuguesa'
ON CONFLICT (content_hash) DO UPDATE SET
  alternativas = EXCLUDED.alternativas, correta = EXCLUDED.correta, categoria = EXCLUDED.categoria,
  dificuldade = EXCLUDED.dificuldade, explicacao = EXCLUDED.explicacao, topico = EXCLUDED.topico, nivel = EXCLUDED.nivel
WHERE questions.origem = 'autoral';
INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Assinale a frase que está de acordo com a norma-padrão quanto à concordância verbal.', ARRAY['Devem haver servidores suficientes na recepção.', 'Haviam muitas emendas a serem analisadas.', 'Fazem dois anos que o projeto tramita na Câmara.', 'Existem documentos que precisam ser protocolados hoje.']::text[], 3, 'Língua Portuguesa', 'Médio', '''Existir'' é pessoal e concorda com ''documentos''. ''Fazer'' indicando tempo e ''haver'' no sentido de existir são impessoais (faz, havia, deve haver).', s.id, false, 'Concordância verbal', 'autoral', NULL, '34b672453d19948f3e9917f30cada0c4ec65b4df9e1b482b40720ca859a7fb6c'
FROM public.subjects s WHERE s.slug = 'cmc26-lingua-portuguesa'
ON CONFLICT (content_hash) DO UPDATE SET
