INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Assinale a opção em que a regência nominal está correta.', ARRAY['Ela é muito devota com a causa pública.', 'A população tem aversão com a burocracia.', 'O projeto é compatível para o orçamento.', 'O servidor estava apto a assumir a função.']::text[], 3, 'Língua Portuguesa', 'Médio', '''Apto a'' é regência correta. O padrão seria ''aversão a'', ''devota a/de'' e ''compatível com''.', s.id, false, 'Regência nominal', 'autoral', NULL, '95483fc9a723ed1e92e2eba734a2227ca0ba45103da8f76da63b3946eb69d7aa'
FROM public.subjects s WHERE s.slug = 'cmc26-lingua-portuguesa'
