INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'De acordo com a norma-padrão, a colocação pronominal está correta em:', ARRAY['Tinha informado-me sobre o prazo.', 'Me informaram que a sessão foi suspensa.', 'Não esqueça-se de assinar o termo de posse.', 'Quando se aprovou a lei, houve comemoração.']::text[], 3, 'Língua Portuguesa', 'Médio', 'A conjunção subordinativa ''quando'' atrai o pronome (próclise). Não se inicia período com pronome oblíquo átono; ''não'' exige próclise; não se usa ênclise a particípio (''tinha-me informado'').', s.id, false, 'Colocação pronominal', 'autoral', NULL, 'fa863a244e70640365f875068d1626240c348bba451c1d0678e9670959b95d98'
FROM public.subjects s WHERE s.slug = 'cmc26-lingua-portuguesa'
