INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Assinale a alternativa em que a mesóclise é obrigatória segundo a norma-padrão.', ARRAY['Não se convidarão os vereadores para a sessão solene.', 'Os vereadores se convidarão para a sessão solene.', 'Quem se convidará para a sessão solene?', 'Convidar-se-ão os vereadores para a sessão solene.']::text[], 3, 'Língua Portuguesa', 'Difícil', 'Com verbo no futuro do presente/pretérito em início de oração, sem fator de próclise, usa-se a mesóclise. Nas demais há fator de próclise (''não'', pronome interrogativo) ou sujeito anteposto que permite a próclise.', s.id, false, 'Colocação pronominal', 'autoral', NULL, 'eb2c369c9eea368892bf742ff33b4f4305dbbd65931fa1aeb8bc2af4ed437212'
