INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Assinale a frase pontuada corretamente.', ARRAY['Cuiabá capital de Mato Grosso, completou 300 anos em 2019.', 'Os vereadores, aprovaram o projeto por unanimidade.', 'Na sessão de ontem foram votados, três projetos.', 'O presidente da Câmara, que presidia a sessão, encerrou os trabalhos.']::text[], 3, 'Língua Portuguesa', 'Médio', 'A oração adjetiva explicativa vem entre vírgulas. Não se separa sujeito do verbo nem verbo do complemento; o aposto ''capital de Mato Grosso'' deveria estar entre vírgulas.', s.id, false, 'Pontuação', 'autoral', NULL, '80958173fefee24445e9d9ec64a91cec7b0b26be575a5a5de9348e002444b2fa'
