INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Em "Os servidores que trabalham na recepção receberão treinamento", a inserção de vírgulas antes de "que" e depois de "recepção":', ARRAY['manteria o sentido, pois a vírgula é facultativa nesse caso', 'transformaria a oração em adverbial de causa', 'alteraria o sentido, pois indicaria que todos os servidores trabalham na recepção', 'tornaria a frase incorreta, pois não se usa vírgula antes de pronome relativo']::text[], 2, 'Língua Portuguesa', 'Difícil', 'Sem vírgulas, a oração é restritiva (só os servidores da recepção). Com vírgulas, passa a explicativa, generalizando: todos os servidores (que, aliás, trabalham na recepção).', s.id, false, 'Pontuação', 'autoral', NULL, '6d7a2824aa372e4de10d2297ac69b9474b699a9df8def7c57f3ba3c8af8f0961'
