INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Em "O projeto foi aprovado, embora houvesse resistência da oposição", a conjunção "embora" pode ser substituída, sem prejuízo do sentido, por:', ARRAY['porque', 'contanto que', 'portanto', 'conquanto']::text[], 3, 'Língua Portuguesa', 'Médio', '''Embora'' e ''conquanto'' são concessivas. ''Porque'' é causal, ''portanto'' é conclusiva e ''contanto que'' é condicional.', s.id, false, 'Conjunções', 'autoral', NULL, '77814be3007bd4df8bf0ed7ac4d9a871990e4bb947869d1af9be8c79ff19edea'
