INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'A relação de sentido estabelecida pelo conectivo destacado está corretamente indicada em:', ARRAY['"SE houver quórum, a votação ocorrerá" — finalidade', '"Estudou muito, LOGO foi aprovado" — explicação', '"Chegou cedo, PORÉM a sessão já havia começado" — adversidade', '"Saiu cedo PARA QUE não perdesse o ônibus" — consequência']::text[], 2, 'Língua Portuguesa', 'Médio', '''Porém'' é adversativa. ''Logo'' é conclusiva; ''se'' é condicional; ''para que'' é final.', s.id, false, 'Conjunções', 'autoral', NULL, '9e7b76038dd6958c1bf44fc83c247b24d9f755555016235e5856ca9b33f54d41'
