INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Conforme o Acordo Ortográfico vigente, ambas as palavras estão grafadas corretamente em:', ARRAY['auto-estima e anti-inflamatório', 'contra-regra e semi-árido', 'micro-ondas e autoescola', 'anti-social e micro-ondas']::text[], 2, 'Língua Portuguesa', 'Médio', 'Usa-se hífen quando o prefixo termina na mesma vogal que inicia o segundo elemento (micro-ondas, anti-inflamatório) e não se usa quando as vogais são diferentes (autoescola, autoestima, antissocial — dobrando o s) ou diante de r/s (contrarregra). ''Semiárido'' perdeu o hífen e mantém o acento.', s.id, false, 'Uso do hífen', 'autoral', NULL, '3d179f764cdf700418d61163c74ca8dc6a45b42153473672eb94448d4fca93e9'
