INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Expressões típicas do falar cuiabano, como "pai-dégua" e "tchá por Deus", são exemplos de variação linguística:', ARRAY['diatópica (regional)', 'diacrônica (histórica)', 'que constitui erro de português', 'diafásica (situacional)']::text[], 0, 'Língua Portuguesa', 'Fácil', 'A variação geográfica/regional é chamada diatópica. A Selecon cobra o respeito às variedades: não se trata de ''erro'', mas de adequação ao contexto.', s.id, false, 'Variação linguística', 'autoral', NULL, '14ec81c9d5a26b1426fb9803d4b1fa966b5f9fc6d90dfdadab29b0475d18456c'
