INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Um servidor usa linguagem formal ao redigir um ofício e linguagem coloquial ao conversar com colegas no intervalo. Isso exemplifica a variação:', ARRAY['diastrática', 'diafásica', 'diatópica', 'diacrônica']::text[], 1, 'Língua Portuguesa', 'Médio', 'Diafásica é a variação conforme a situação comunicativa (registro formal x informal). Diastrática relaciona-se a grupos sociais; diacrônica, ao tempo.', s.id, false, 'Variação linguística', 'autoral', NULL, '486f169e2f526497e19934586ec816f24322bc33cec41e2e81178d71e92725e7'
