INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Considerando a adequação ao registro formal exigido em um requerimento à Mesa Diretora, a melhor redação é:', ARRAY['Tô pedindo pra botar o projeto na pauta, valeu.', 'Exijo a imediata colocação do projeto em pauta!', 'Venho, respeitosamente, requerer a Vossa Excelência a inclusão da matéria na pauta.', 'Gostaria que vocês colocassem a matéria na pauta aí.']::text[], 2, 'Língua Portuguesa', 'Médio', 'Formalidade, impessoalidade, polidez e pronome de tratamento adequado caracterizam a redação oficial; as demais são coloquiais ou descorteses.', s.id, false, 'Registro formal e informal', 'autoral', NULL, '61ba2c319aa4ddd50356d3f5294138ce3ee12cfa3b89be35d52398bdcda675bc'
