INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Transpondo para o discurso indireto a frase "O presidente afirmou: — Encerro a sessão agora.", obtém-se:', ARRAY['O presidente afirmou que encerrará a sessão agora.', 'O presidente afirmou: encerrava a sessão naquele momento.', 'O presidente afirmou que encerrava a sessão naquele momento.', 'O presidente afirmou que encerro a sessão agora.']::text[], 2, 'Língua Portuguesa', 'Médio', 'No discurso indireto, o presente passa a pretérito imperfeito (''encerrava''), a 1ª pessoa passa a 3ª e ''agora'' vira ''naquele momento''.', s.id, false, 'Discurso direto e indireto', 'autoral', NULL, '17d5bf58b0c3f5639905ed22dcd45dad41e62d9f2571b72b622a16978c68d050'
