INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Assinale a transposição correta de "A vereadora perguntou: — Vocês já leram o parecer?" para o discurso indireto.', ARRAY['A vereadora perguntou se eles já leriam o parecer.', 'A vereadora perguntou se vocês já leram o parecer.', 'A vereadora perguntou que eles já leram o parecer?', 'A vereadora perguntou se eles já tinham lido o parecer.']::text[], 3, 'Língua Portuguesa', 'Difícil', 'Pergunta direta vira oração com ''se''; ''vocês'' passa a ''eles'' e o pretérito perfeito (''leram'') passa ao mais-que-perfeito (''tinham lido'').', s.id, false, 'Discurso direto e indireto', 'autoral', NULL, '827c5e7c68419db21df7c5a47bc13fe2a743f94597fcd25ddfe645b3e507a17d'
