INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Assinale a alternativa em que o pronome está empregado de acordo com a norma-padrão.', ARRAY['Trouxe o relatório para mim revisar.', 'Este documento que está em minhas mãos é o original.', 'Isto que você disse ontem foi importante.', 'Entre eu e você não há problemas.']::text[], 1, 'Língua Portuguesa', 'Médio', '''Este'' refere-se ao que está próximo de quem fala. O correto seria ''isso que você disse'' (próximo ao interlocutor/passado recente), ''entre mim e você'' e ''para eu revisar'' (sujeito de infinitivo).', s.id, false, 'Emprego de pronomes', 'autoral', NULL, '1ff9a011019ec31807e3abc303e2aef3da297f64f9c428c38b36028b302268a3'
