INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Ao se dirigir diretamente ao Presidente da Câmara Municipal, em correspondência oficial, a concordância correta é:', ARRAY['Sua Excelência sabeis que o prazo terminou.', 'Vossa Excelência sabe que vosso prazo terminou.', 'Vossa Excelência sabe que seu prazo terminou.', 'Vossa Excelência sabeis que o prazo terminou.']::text[], 2, 'Língua Portuguesa', 'Médio', 'Pronomes de tratamento levam o verbo e os possessivos à 3ª pessoa: ''Vossa Excelência sabe... seu prazo''. ''Sua Excelência'' é usado para falar sobre a autoridade, não com ela.', s.id, false, 'Pronomes de tratamento', 'autoral', NULL, '0edc2a43a14530678577917080cdf19d03d3fd3ba6bd7c9908d2e7241c1c5292'
