INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Assinale a alternativa correta quanto ao emprego do infinitivo, segundo a norma-padrão.', ARRAY['Os vereadores pediram para nós aguardar.', 'Eles começaram a discutirem o projeto.', 'Para os candidatos serem aprovados, precisam estudar.', 'Os servidores insistiram em entrarem no plenário.']::text[], 2, 'Língua Portuguesa', 'Difícil', 'O infinitivo flexiona quando tem sujeito próprio expresso (''os candidatos serem''; ''para nós aguardarmos''). Em locuções verbais e quando o sujeito é o mesmo do verbo principal (''insistiram em entrar'', ''começaram a discutir''), o infinitivo não se flexiona.', s.id, false, 'Emprego do infinitivo', 'autoral', NULL, '97bd15bfd48bc7bca6eec29929871c9f84980f39398ffb63d5fb095ea2d7eb5a'
