INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Assinale a reescrita que mantém o sentido e a correção de "Os servidores, portanto, devem cumprir o horário".', ARRAY['Os servidores devem, portanto, cumprir o horário.', 'Os servidores, porém, devem cumprir o horário.', 'Portanto os servidores, devem cumprir o horário.', 'Os servidores devem portanto, cumprir o horário.']::text[], 0, 'Língua Portuguesa', 'Médio', 'A conjunção conclusiva deslocada fica entre vírgulas. B muda o sentido (adversidade); C e D têm vírgula mal empregada.', s.id, false, 'Vírgula e conectivos', 'autoral', NULL, '5203a349c21b6eb50475832e82a40af3992777733948b7971e6b11440029fb99'
