INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'O bandeirante associado à descoberta de ouro às margens do rio Coxipó e à ata de fundação do arraial que daria origem a Cuiabá, em 8 de abril de 1719, é:', ARRAY['Borba Gato', 'Pascoal Moreira Cabral', 'Antônio Raposo Tavares', 'Fernão Dias Paes']::text[], 1, 'História e Geografia de Mato Grosso', 'Fácil', 'Pascoal Moreira Cabral liderou a bandeira que encontrou ouro no Coxipó-Mirim; a ata de 8/4/1719 marca a fundação do arraial (data comemorada como aniversário de Cuiabá).', s.id, false, 'Colônia - fundação de Cuiabá', 'autoral', NULL, '2e2196c834d0790f714079e9394a01602be515d1ae3686b719a2276f6517e5de'
