INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Em 1722, a descoberta de ricas jazidas de ouro no local onde hoje está o centro histórico de Cuiabá (região da Igreja do Rosário) é atribuída a:', ARRAY['Rodrigo César de Menezes', 'Bartolomeu Bueno', 'Miguel Sutil', 'Rolim de Moura']::text[], 2, 'História e Geografia de Mato Grosso', 'Médio', 'As ''Lavras do Sutil'', descobertas por Miguel Sutil, deslocaram o núcleo minerador para o atual centro da cidade.', s.id, false, 'Colônia - Lavras do Sutil', 'autoral', NULL, 'ae8a07cbbb847f525a64b969f2a4f283907843fc8a246563dd6f5ad4a722cd7e'
