INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Em 1º de janeiro de 1727, o arraial de Cuiabá foi elevado à categoria de vila, com o nome de:', ARRAY['Vila Maria do Paraguai', 'Vila Bela da Santíssima Trindade', 'Vila Real do Senhor Bom Jesus de Cuiabá', 'Vila Rica do Ouro Preto']::text[], 2, 'História e Geografia de Mato Grosso', 'Médio', 'A elevação foi feita pelo governador da Capitania de São Paulo, Rodrigo César de Menezes, que veio pessoalmente às minas.', s.id, false, 'Colônia - Vila Real', 'autoral', NULL, 'e12f138f4eb11af25dedf6ce09df518553c8b3d1f20914507996cc161820c113'
