INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'A presença do governador Rodrigo César de Menezes nas minas de Cuiabá (1726-1728) é associada:', ARRAY['à abolição dos quintos sobre o ouro', 'ao aumento do controle fiscal da Coroa sobre o ouro, gerando tensões com os mineradores e fundadores', 'à expulsão dos jesuítas da região', 'à transferência da capital do Brasil para Cuiabá']::text[], 1, 'História e Geografia de Mato Grosso', 'Médio', 'A chegada da administração colonial trouxe cobrança rigorosa de tributos (quinto), cargos e controle, gerando conflitos com os primeiros povoadores (como os irmãos Leme).', s.id, false, 'Colônia - tensões políticas', 'autoral', NULL, 'e3361a0c66ec731fd2a58ee9972db36544d0db30d1b7c2638db81e90e71dc6fe'
