INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'As monções, importantes para o abastecimento e o povoamento de Cuiabá no século XVIII, eram:', ARRAY['caravanas de tropeiros vindas do Rio Grande do Sul', 'expedições fluviais que partiam de São Paulo (Porto Feliz, no rio Tietê) rumo às minas cuiabanas', 'ventos sazonais que facilitavam a navegação no Pantanal', 'navios que subiam o rio Amazonas a partir de Belém exclusivamente']::text[], 1, 'História e Geografia de Mato Grosso', 'Médio', 'As monções percorriam rios (Tietê, Paraná, Pardo, Taquari, Paraguai, Cuiabá) em longas e perigosas viagens, enfrentando ataques de indígenas Paiaguá e Guaicuru.', s.id, false, 'Colônia - monções', 'autoral', NULL, '24fe5de3d3bcd42ca0455744c78dbc6b274890e60741e85ee08dff969dae1e58'
