INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Os povos indígenas que, no século XVIII, ofereceram forte resistência às monções nos rios do Pantanal, conhecidos respectivamente como "canoeiros" e "cavaleiros", foram os:', ARRAY['Paiaguá e Guaicuru', 'Kayabi e Bakairi', 'Bororo e Xavante', 'Paresi e Nambikwara']::text[], 0, 'História e Geografia de Mato Grosso', 'Médio', 'Os Paiaguá atacavam com canoas nos rios; os Guaicuru (Mbayá), exímios cavaleiros, dominavam as planícies.', s.id, false, 'Colônia - indígenas', 'autoral', NULL, '29d61af5cae3364f1df2e2625e12e1fd6fe3d2e59ce1f4bdbde6ffe77e0b6580'
