INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'A Capitania de Mato Grosso foi criada em 1748, separada da Capitania de São Paulo, tendo como objetivo central:', ARRAY['garantir a posse portuguesa da fronteira oeste diante dos domínios espanhóis', 'implantar missões jesuíticas', 'organizar a produção de café', 'transferir a mineração para o litoral']::text[], 0, 'História e Geografia de Mato Grosso', 'Médio', 'A criação da capitania inseria-se na estratégia geopolítica portuguesa de ocupação da fronteira (consolidada no Tratado de Madri, 1750, pelo princípio do uti possidetis).', s.id, false, 'Colônia - Capitania', 'autoral', NULL, '347fb881b51f9e7a7a0edc32b70965f026a20b65580f9f7de2eae83480dd001c'
