INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Vila Bela da Santíssima Trindade, primeira capital da Capitania de Mato Grosso, foi fundada em 1752, às margens do rio Guaporé, por:', ARRAY['Rodrigo César de Menezes', 'Antônio Rolim de Moura Tavares', 'Luís de Albuquerque', 'Pascoal Moreira Cabral']::text[], 1, 'História e Geografia de Mato Grosso', 'Médio', 'Rolim de Moura, primeiro governador da capitania, fundou Vila Bela em 19 de março de 1752, em posição estratégica junto à fronteira espanhola.', s.id, false, 'Colônia - Vila Bela', 'autoral', NULL, '09753845a1f2dc4675c591896b90fecccb6d5e0e2262aca4c72ce1a397d1d68b'
