INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'O princípio jurídico que fundamentou o Tratado de Madri (1750), favorável à manutenção dos territórios ocupados pelos portugueses no oeste, foi o:', ARRAY['padroado régio', 'direito de conquista papal', 'Tratado de Tordesilhas', 'uti possidetis']::text[], 3, 'História e Geografia de Mato Grosso', 'Médio', 'Uti possidetis: a terra pertence a quem efetivamente a ocupa — o que legitimou a presença lusa em Mato Grosso.', s.id, false, 'Colônia - Tratado de Madri', 'autoral', NULL, '4decab4c516bcf21a7ab7d57e7e0b053b24a8b208b220d2d72f4e3e0b3333d1a'
