INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'No período colonial, foram construídos para defender a fronteira oeste, entre outros:', ARRAY['o Forte do Presépio e o Forte Orange', 'a Fortaleza de Santa Cruz e o Forte de Copacabana', 'o Forte Príncipe da Beira, no Guaporé, e o Forte de Coimbra, no rio Paraguai', 'o Forte dos Reis Magos e o Forte de São Marcelo']::text[], 2, 'História e Geografia de Mato Grosso', 'Médio', 'Os fortes Príncipe da Beira (Guaporé) e Coimbra (rio Paraguai), ambos da década de 1770, protegiam a fronteira com os domínios espanhóis.', s.id, false, 'Colônia - fortificações', 'autoral', NULL, '34a1ebd4e892f2f917f61c6b79dee28c06c47fc11ad74a282f84bc5d236134f4'
