INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Sobre a escravidão negra em Mato Grosso no período colonial, é correto afirmar que:', ARRAY['africanos escravizados foram trazidos em grande número para a mineração e outras atividades, resistindo por meio de fugas e quilombos', 'os escravizados vieram exclusivamente da Amazônia espanhola', 'a escravidão foi abolida em Mato Grosso no século XVIII', 'não houve escravidão africana em Mato Grosso, apenas indígena']::text[], 0, 'História e Geografia de Mato Grosso', 'Médio', 'A mineração cuiabana e guaporeana empregou intensamente mão de obra africana escravizada, que resistiu formando quilombos.', s.id, false, 'Colônia - escravidão', 'autoral', NULL, '2cb1a54c7823dc8ea653510ba90a3a5f8bb6e687adb406e927bd90c2a71175c0'
