INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Com o esgotamento do ouro de aluvião, no final do século XVIII e no século XIX, a economia mato-grossense passou a se apoiar em alternativas como:', ARRAY['pecuária, agricultura de subsistência, cana-de-açúcar e, depois, extrativismo (poaia, borracha, erva-mate)', 'indústria têxtil de grande porte', 'cafeicultura de exportação', 'extração de petróleo']::text[], 0, 'História e Geografia de Mato Grosso', 'Médio', 'A decadência mineradora levou à diversificação: criação de gado, engenhos, roças e extrativismo vegetal.', s.id, false, 'Império - crise da mineração', 'autoral', NULL, '7c9b89f30541852fc1bc8c1027095b894597f4b788402e577e97697bb9d29d13'
