INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'A Rusga, ocorrida em Cuiabá em 30 de maio de 1834, foi:', ARRAY['uma revolta de escravizados pela abolição', 'um conflito entre Mato Grosso e Goiás por limites', 'um levante nativista, no período regencial, marcado por ataques e mortes de portugueses (os ''bicudos'')', 'uma guerra contra o Paraguai']::text[], 2, 'História e Geografia de Mato Grosso', 'Médio', 'Inserida nas agitações regenciais, a Rusga opôs grupos liberais/nativistas (ligados à Sociedade dos Zelosos da Independência) aos portugueses, resultando em mortes e saques.', s.id, false, 'Império - Rusga', 'autoral', NULL, 'bd83775894ae13d057b1f4be8f63792c2f450988b01247c19e741455d9868275'
