INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'No Império, a Província de Mato Grosso era administrada por presidentes de província que eram:', ARRAY['indicados pelo governo do Paraguai', 'eleitos diretamente pelo voto popular', 'nomeados pelo Imperador, muitas vezes vindos de outras regiões', 'escolhidos pela Câmara Municipal de Cuiabá']::text[], 2, 'História e Geografia de Mato Grosso', 'Difícil', 'Os presidentes de província eram nomeados pelo poder central, o que expressava a centralização política do Império.', s.id, false, 'Império - presidentes de província', 'autoral', NULL, '5a5669deb855070e650e6026d360cc51334e519646f95f67d4aa3ef75d506ae8'
