INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'No início da Guerra da Tríplice Aliança (1864-1870), Mato Grosso:', ARRAY['permaneceu fora do conflito', 'foi anexado pela Bolívia', 'foi o principal fornecedor de armas ao Paraguai', 'teve o sul de seu território invadido por tropas paraguaias, com ataque ao Forte de Coimbra e ocupação de Corumbá']::text[], 3, 'História e Geografia de Mato Grosso', 'Médio', 'Em dezembro de 1864, forças paraguaias invadiram o sul de Mato Grosso, atacando Coimbra e ocupando Corumbá e outras localidades.', s.id, false, 'Guerra do Paraguai', 'autoral', NULL, '4da8edaf7ee05f47aa7907406bb3fdac8da08798f3d6f4b0bb89366c96729b01'
