INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Em 1867, a retomada de Corumbá pelas forças mato-grossenses foi seguida de uma grave epidemia que atingiu Cuiabá e matou grande parte da população. Trata-se da epidemia de:', ARRAY['varíola', 'febre amarela urbana de 1918', 'gripe espanhola', 'peste bubônica']::text[], 0, 'História e Geografia de Mato Grosso', 'Difícil', 'Tropas que retornavam de Corumbá trouxeram a varíola, que dizimou parcela expressiva da população cuiabana.', s.id, false, 'Guerra do Paraguai', 'autoral', NULL, 'dd41e63f9293005fdacd0182b7aaa781f4eceba9bab1823a6658172f0d8f6c4d'
