INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Após a Guerra do Paraguai, a livre navegação pelo rio Paraguai favoreceu Mato Grosso porque:', ARRAY['permitiu o transporte ferroviário até Cuiabá', 'isolou a província do restante do país', 'encerrou as atividades comerciais com Buenos Aires', 'ligou a província ao Atlântico via Rio da Prata, impulsionando o comércio e o porto de Corumbá']::text[], 3, 'História e Geografia de Mato Grosso', 'Médio', 'A rota fluvial pela bacia platina tornou-se a principal ligação comercial, e Corumbá tornou-se importante entreposto.', s.id, false, 'Pós-guerra - economia', 'autoral', NULL, '0750e109b5853e5f6c8815e49794e3df5ad3be11b8f6887f4c363332a0e3060e'
