INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Em 1906, um movimento armado liderado por Generoso Ponce resultou na morte do governador de Mato Grosso, que era proprietário da Usina Itaici. Esse governador era:', ARRAY['Pedro Celestino', 'Júlio Müller', 'Antônio Paes de Barros (Totó Paes)', 'Mário Corrêa da Costa']::text[], 2, 'História e Geografia de Mato Grosso', 'Difícil', 'Totó Paes, usineiro do rio Cuiabá, foi deposto e morto em 1906 — episódio emblemático das disputas oligárquicas da época.', s.id, false, 'República - coronelismo', 'autoral', NULL, '9db30f720613a16b6490aa51b8ac3fd534f870aa7179531d56079639065a7170'
