INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Costuma-se afirmar que a Filosofia nasceu na Grécia, por volta do século VI a.C., marcando a passagem:', ARRAY['da ciência moderna para a religião', 'do pensamento mítico para o pensamento racional (do mito ao logos)', 'da escrita para a oralidade', 'do pensamento racional para o religioso']::text[], 1, 'Noções de Ética e Filosofia', 'Médio', 'Os primeiros filósofos (pré-socráticos, como Tales de Mileto) buscaram explicações racionais (logos) para a origem e a ordem do mundo, em vez de narrativas míticas.', s.id, false, 'Fundamentos da Filosofia', 'autoral', NULL, '3a6e7e6b4b0c137d463cff1ccb93d878f4b0d80353b118e7e4546c54b04f5ce4'
