INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'A atitude filosófica, segundo Marilena Chaui, caracteriza-se inicialmente por:', ARRAY['rejeição de qualquer forma de pensamento racional', 'aceitação das opiniões estabelecidas', 'busca de respostas definitivas por meio da fé', 'uma atitude crítica de recusa do óbvio e de interrogação sobre o que são as coisas, como são e por que são']::text[], 3, 'Noções de Ética e Filosofia', 'Médio', 'A atitude filosófica é ''negativa'' (diz não ao senso comum e aos preconceitos) e ''positiva'' (interroga o que, como e por que).', s.id, false, 'Fundamentos da Filosofia', 'autoral', NULL, '8e585e5808f3e9525cb7b9672977c3d3761bfc1b975621136ad97b964ebc447d'
