INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'A palavra "ética" vem do grego ethos e "moral" vem do latim mos/mores. Ambas se referem, na origem, a:', ARRAY['ciência da natureza', 'costumes e caráter', 'religião organizada', 'leis escritas']::text[], 1, 'Noções de Ética e Filosofia', 'Fácil', 'Ethos e mores remetem aos costumes e ao modo de ser (caráter); por isso ética e moral têm parentesco etimológico.', s.id, false, 'Ética e moral', 'autoral', NULL, 'eac1ecf878f0051c008547703a45375fcf6fb29273dc0ad0737986d6a69bde7a'
