INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Segundo Chaui, para que haja conduta ética é preciso existir o agente moral, que deve ser:', ARRAY['indiferente às consequências', 'obediente, temeroso e passivo', 'consciente, dotado de vontade, responsável e livre', 'subordinado a uma autoridade externa em todas as decisões']::text[], 2, 'Noções de Ética e Filosofia', 'Médio', 'O sujeito ético conhece o bem e o mal, delibera, responde por seus atos e pode autodeterminar-se.', s.id, false, 'Ética e moral', 'autoral', NULL, '5793fe2218797fdf744d7892fc6abb250e975373c0bb55c3e7fc007b722da5f0'
