INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'No serviço público, a ética e a cidadania se relacionam porque:', ARRAY['o servidor deve agir em função do interesse público, com respeito, transparência e igualdade de tratamento a todos os cidadãos', 'as normas éticas não se aplicam aos servidores', 'o servidor deve privilegiar quem tem mais influência', 'o atendimento pode variar conforme a simpatia pessoal']::text[], 0, 'Noções de Ética e Filosofia', 'Médio', 'A ética pública exige impessoalidade, moralidade e compromisso com o bem comum — também princípios do art. 37 da CF.', s.id, false, 'Ética e cidadania', 'autoral', NULL, '679782ea21a777b975c447a9c0da3c6126f134c64c469aca85361ea872246242'
