INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Um servidor percebe que pode obter vantagem pessoal usando informação privilegiada sobre uma licitação. A conduta ética esperada é:', ARRAY['compartilhar a informação apenas com familiares', 'não utilizar a informação e zelar pelo interesse público, comunicando eventual irregularidade', 'usar a informação se ninguém descobrir', 'vender a informação para equilibrar o salário']::text[], 1, 'Noções de Ética e Filosofia', 'Médio', 'Usar informação privilegiada fere a moralidade e a impessoalidade, podendo configurar improbidade administrativa.', s.id, false, 'Ética e cidadania', 'autoral', NULL, '2896dc574df6bdce11629408e70b78a0d60fea5bc475b61d6a4a8b96127e5697'
