INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Maquiavel, em O Príncipe, é frequentemente lembrado por:', ARRAY['defender que o governante deve ser sempre bondoso, ainda que perca o poder', 'separar a análise da política das normas da moral cristã tradicional, focando na conquista e manutenção do poder', 'propor a democracia direta', 'negar qualquer papel do Estado']::text[], 1, 'Noções de Ética e Filosofia', 'Difícil', 'Maquiavel inaugura uma visão realista da política; a frase ''os fins justificam os meios'' é atribuição popular, não literal.', s.id, false, 'Ética e política', 'autoral', NULL, '4a4e3b9cf5a40dcaa8c4a894452fb0b0f0094e4c89a91a1306f58d3905db12e6'
