INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'A diferença central entre a ética aristotélica e a ética kantiana está em que:', ARRAY['a primeira busca a felicidade pela formação de virtudes, e a segunda fundamenta a moral no dever racional, independentemente da felicidade', 'a primeira é consequencialista e a segunda é teleológica', 'ambas rejeitam o uso da razão', 'ambas fundam a moral no prazer']::text[], 0, 'Noções de Ética e Filosofia', 'Difícil', 'Aristóteles: ética teleológica das virtudes. Kant: ética deontológica do dever.', s.id, false, 'Ética das virtudes x dever', 'autoral', NULL, '31bf96bb6d6567de696f7828f3ee776a6b4c248760d0d1dc245be3025eb17077'
