INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'No racionalismo ético, a relação entre razão e paixões costuma ser pensada de modo que:', ARRAY['paixões e razão não têm relação com a ética', 'a razão deve ser eliminada', 'as paixões devem governar a razão', 'a razão deve orientar e moderar as paixões para que a ação seja virtuosa']::text[], 3, 'Noções de Ética e Filosofia', 'Médio', 'Para a tradição racionalista (Sócrates, Platão, Aristóteles, estoicos, Kant), o sujeito ético é aquele que controla os impulsos pela razão.', s.id, false, 'Ética e paixões', 'autoral', NULL, 'e680e69b7d77b0e6729d3689195b37001d5379db58ac1c4db89bfd9236195e57'
