INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Os filósofos estoicos defendiam que a vida virtuosa consiste em:', ARRAY['seguir apenas os próprios desejos', 'buscar o máximo de prazeres sensíveis', 'viver de acordo com a natureza e a razão, aceitando com serenidade o que não depende de nós', 'rejeitar qualquer dever social']::text[], 2, 'Noções de Ética e Filosofia', 'Médio', 'O estoicismo (Zenão, Sêneca, Epicteto, Marco Aurélio) valoriza a apatheia (domínio das paixões) e a razão universal.', s.id, false, 'Estoicismo', 'autoral', NULL, '73f2475884310be8b2a4d53e6a9ac20eb3fa72043afc658f03d59c91f406290d'
