INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Para Epicuro, a felicidade consiste em:', ARRAY['obediência rigorosa às leis do Estado', 'prazeres intensos e ilimitados', 'prazeres moderados, ausência de dor no corpo e de perturbação na alma (ataraxia)', 'acumular riquezas e poder']::text[], 2, 'Noções de Ética e Filosofia', 'Médio', 'O epicurismo não é hedonismo desenfreado: valoriza prazeres simples, a amizade e a tranquilidade.', s.id, false, 'Epicurismo', 'autoral', NULL, 'b9bd464a1b0a9a556b11848884f73a10f3d26adac71ec752f64979c65057c36c'
