INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Segundo Chaui, na ética os meios para atingir um fim:', ARRAY['só importam se forem eficientes', 'são indiferentes, desde que o fim seja bom', 'devem ser compatíveis com os fins éticos, pois não se pode alcançar um fim moral por meios imorais', 'são definidos exclusivamente pela lei']::text[], 2, 'Noções de Ética e Filosofia', 'Médio', 'Para a ética, fins e meios devem ser éticos; meios violentos ou desonestos contaminam o próprio fim.', s.id, false, 'Ética e meios e fins', 'autoral', NULL, 'ac8741e8abd3ce7b73808ef90ac0aa1922a5626a1fc2ddbcd94c312691d25086'
