INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Para Chaui, a violência é contrária à ética porque:', ARRAY['trata o ser humano como coisa, desrespeitando sua condição de sujeito racional, livre e dotado de vontade', 'é sempre ilegal', 'impede o crescimento econômico', 'é praticada apenas por criminosos']::text[], 0, 'Noções de Ética e Filosofia', 'Médio', 'A violência reduz a pessoa à condição de objeto, negando-lhe a autonomia; por isso é o oposto da ética.', s.id, false, 'Violência e ética', 'autoral', NULL, 'c9fbd2f21e63c1de6c84c2ac1e9399d6cd3ef1f551ecf4fd3ee47fa5530fb420'
