INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'No pensamento crítico, alienação designa a situação em que:', ARRAY['há debate livre de ideias', 'as pessoas estão plenamente conscientes de seus direitos', 'os trabalhadores controlam o processo produtivo', 'os indivíduos não se reconhecem como produtores de sua realidade social, que lhes aparece como estranha e natural']::text[], 3, 'Noções de Ética e Filosofia', 'Médio', 'Alienar é tornar alheio: o que é produção humana aparece como força externa e inevitável.', s.id, false, 'Alienação', 'autoral', NULL, '96b0c46e781369a03dd754bf1b2f71da5c5eb35aea3bf807b2bf50b72170f418'
