INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'No registro sonoro das sessões plenárias, para garantir preservação e consulta futura, é recomendável:', ARRAY['gravar em formato de alta qualidade, nomear e catalogar os arquivos com metadados (data, sessão) e manter cópias de segurança em locais distintos', 'manter um único arquivo no computador da mesa de som', 'dispensar a gravação quando houver transmissão ao vivo', 'gravar apenas em MP3 de baixa taxa e apagar após a ata']::text[], 0, 'Técnico Legislativo — Sonorização', 'Médio', 'Gravações de sessões são registros públicos: organização, metadados e backup (regra 3-2-1) garantem integridade e acesso.', s.id, false, 'Gravação de sessões', 'autoral', NULL, '8f21a64b27d16af7c1136dc2af76eca5b27e1b4b48ecfef7cfe8c19e084d0009'
