INSERT INTO public.questions (enunciado, alternativas, correta, categoria, dificuldade, explicacao, subject_id, is_premium, topico, origem, nivel, content_hash)
SELECT 'Uma mesa terá 5 lugares, com as autoridades A (maior precedência, preside), B, C, D e E, em ordem decrescente. Da esquerda para a direita de quem olha da plateia, a disposição correta é:', ARRAY['D, B, A, C, E', 'B, D, A, E, C', 'E, C, A, B, D', 'A, B, C, D, E']::text[], 0, 'Técnico Legislativo — Cerimonial', 'Difícil', 'A no centro; B à direita de A (que, para a plateia, é o lado esquerdo); C à esquerda de A; D à direita de B; E à esquerda de C. Visto da plateia: D, B, A, C, E.', s.id, false, 'Composição de mesa', 'autoral', NULL, '851314adc0fde874817a5fbcef0e087518bbfd56b6e883f996ff433ac052d88a'
